def _static_extra_paths() -> list[str]:
    """构造与平台无关的额外搜索目录（不含需要子进程/npm 探测的项）。"""
    home = os.path.expanduser("~")
    dirs = [
        os.path.join(home, ".local", "bin"),
        "/usr/local/bin",
        "/opt/homebrew/bin",           # macOS Apple Silicon Homebrew
        "/usr/bin",
        os.path.join(home, ".bun", "bin"),
        os.path.join(home, ".volta", "bin"),
        os.path.join(home, ".npm-global", "bin"),
        os.path.join(home, ".deno", "bin"),
        os.path.join(home, "bin"),
    ]
    if os.name == "nt":
        local = os.environ.get("LOCALAPPDATA", "")
        appdata = os.environ.get("APPDATA", "")
        if appdata:
            dirs.append(os.path.join(appdata, "npm"))
        if local:
            dirs.append(os.path.join(local, "Programs"))
    return dirs


def _nvm_paths() -> list[str]:
    """nvm 安装的 node 版本目录（按版本号降序，当前版本优先）。"""
    pattern = os.path.join(os.path.expanduser("~"), ".nvm", "versions", "node", "*", "bin")
    found = glob.glob(pattern)
    if not found:
        return []

    def _ver(d: str) -> tuple:
        name = os.path.basename(os.path.dirname(d)) or os.path.basename(d)
        return _version_tuple(name.lstrip("v"))

    return sorted(found, key=_ver, reverse=True)[:3]


def _find_nvm_binary(binary: str) -> Optional[str]:
    """在 nvm 路径中查找 node/npm（不解析符号链接，避免 npm -> npm-cli.js）。"""
    for d in _nvm_paths():
        candidate = os.path.join(d, binary)
        try:
            if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
                return candidate
        except OSError:
            continue
    return None


# npm 全局 bin（需要执行 npm，懒解析 + 进程内缓存）
_npm_bin_cache: dict = {}
_NPM_CACHE_TTL = 300.0


def _npm_global_bin() -> list[str]:
    """通过 `npm prefix -g` 解析 npm 全局 bin 目录（缓存 5 分钟）。"""
    now = time.time()
    cached = _npm_bin_cache.get("dirs")
    if cached is not None and now - _npm_bin_cache.get("ts", 0) < _NPM_CACHE_TTL:
        return cached

    dirs: list[str] = []
    npm = shutil.which("npm")
    if npm:
        try:
            proc = subprocess.run([npm, "prefix", "-g"], capture_output=True,
                                  text=True, timeout=10)
            if proc.returncode == 0:
                prefix = (proc.stdout or "").strip().splitlines()
                if prefix:
                    root = prefix[-1].strip()
                    if root:
                        if os.name == "nt":
                            dirs.append(root)
                        else:
                            dirs.append(os.path.join(root, "bin"))
        except (subprocess.SubprocessError, OSError):
            logger.debug("npm prefix -g 解析失败", exc_info=True)

    _npm_bin_cache["dirs"] = dirs
    _npm_bin_cache["ts"] = now
    return dirs


def _extra_search_paths(include_npm: bool = True) -> list[str]:
    """PATH 回退阶梯的候选目录（去重、保序）。

    include_npm=False 时跳过 `npm prefix -g` 子进程解析（供快速同步检测使用）。
    """
    candidates = _static_extra_paths() + _nvm_paths()
    if include_npm:
        candidates += _npm_global_bin()
    seen: set = set()
    result: list[str] = []
    for d in candidates:
        if not d:
            continue
        norm = os.path.normpath(os.path.expanduser(d))
        if norm in seen or not os.path.isdir(norm):
            continue
        seen.add(norm)
        result.append(norm)
    return result


# 登录 shell PATH 懒解析缓存（GUI/daemon 启动时 PATH 不全的兜底）
_login_shell_path_cache: dict = {}
_CACHE_TTL = 60  # seconds


def _login_shell_candidates() -> list[str]:
    """可用的登录 shell（用户 $SHELL 优先）。"""
    shell = os.environ.get("SHELL", "").strip()
    candidates = [shell] if shell else []
    for fallback in ("/bin/bash", "/bin/zsh", "/bin/sh"):
        if fallback not in candidates:
            candidates.append(fallback)
    return [c for c in candidates if c and os.path.exists(c)]


def _resolve_login_shell_path() -> str:
    """同步解析登录 shell 的 PATH（带 TTL 缓存）。"""
    cached = _login_shell_path_cache.get("path")
    if cached is not None and time.time() - _login_shell_path_cache.get("ts", 0) < _CACHE_TTL:
        return cached

    path = ""
    if os.name != "nt":
        for shell in _login_shell_candidates():
            try:
                proc = subprocess.run(
                    [shell, "-l", "-c", 'printf %s "$PATH"'],
                    capture_output=True, text=True, timeout=6,
                )
            except (subprocess.SubprocessError, OSError):
                logger.debug("登录 shell PATH 解析失败: %s", shell, exc_info=True)
                continue
            out = (proc.stdout or "").strip()
            if proc.returncode == 0 and out:
                path = out
                break

    _login_shell_path_cache["path"] = path
    _login_shell_path_cache["ts"] = time.time()
    return path


async def _get_login_shell_path() -> str:
    """懒解析登录 shell 的 PATH（解决 GUI/daemon 启动时 PATH 不全的问题）。"""
    return await asyncio.to_thread(_resolve_login_shell_path)


def _login_shell_dirs() -> list[str]:
    return [d for d in (_resolve_login_shell_path() or "").split(os.pathsep) if d]


